-- CSDL restman2 cho RestMan2 (MySQL 8.0). Chạy: mysql -u root -p < restman2.sql
SET NAMES utf8mb4;
DROP DATABASE IF EXISTS restman2;
CREATE DATABASE restman2 CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE restman2;

CREATE TABLE tblMember2 (
  id INT AUTO_INCREMENT PRIMARY KEY,
  username VARCHAR(50) NOT NULL UNIQUE,
  password VARCHAR(255) NOT NULL,
  fullName VARCHAR(255) NOT NULL,
  phoneNumber VARCHAR(20) NOT NULL,
  email VARCHAR(255) NULL
);
CREATE TABLE tblEmployee2 (
  tblMember2id INT PRIMARY KEY,
  employeeCode VARCHAR(20) NOT NULL UNIQUE,
  position VARCHAR(50) NOT NULL,
  FOREIGN KEY (tblMember2id) REFERENCES tblMember2(id)
);
CREATE TABLE tblCustomer2 (
  tblMember2id INT PRIMARY KEY,
  customerCode VARCHAR(20) NOT NULL UNIQUE,
  FOREIGN KEY (tblMember2id) REFERENCES tblMember2(id)
);
CREATE TABLE tblMembershipCard2 (
  id INT AUTO_INCREMENT PRIMARY KEY,
  cardCode VARCHAR(20) NOT NULL UNIQUE,
  issueDate DATE NOT NULL,
  `rank` VARCHAR(50) NOT NULL,
  point INT NOT NULL,
  discountRate FLOAT NOT NULL, -- phần trăm giảm, ví dụ 10 = 10%
  tblCustomer2id INT NOT NULL UNIQUE,
  FOREIGN KEY (tblCustomer2id) REFERENCES tblCustomer2(tblMember2id)
);
CREATE TABLE tblSupplier2 (
  id INT AUTO_INCREMENT PRIMARY KEY,
  name VARCHAR(255) NOT NULL,
  address VARCHAR(255) NOT NULL,
  phoneNumber VARCHAR(20) NOT NULL,
  email VARCHAR(255) NULL,
  description VARCHAR(255) NULL
);
CREATE TABLE tblIngredient2 (
  id INT AUTO_INCREMENT PRIMARY KEY,
  name VARCHAR(255) NOT NULL,
  unit VARCHAR(20) NOT NULL,
  stockQuantity FLOAT NOT NULL,
  description VARCHAR(255) NULL
);
CREATE TABLE tblImportReceipt2 (
  id INT AUTO_INCREMENT PRIMARY KEY,
  importTime DATETIME NOT NULL,
  note VARCHAR(255) NULL,
  tblSupplier2id INT NOT NULL,
  tblEmployee2id INT NOT NULL,
  FOREIGN KEY (tblSupplier2id) REFERENCES tblSupplier2(id),
  FOREIGN KEY (tblEmployee2id) REFERENCES tblEmployee2(tblMember2id)
);
CREATE TABLE tblImportedIngredient2 (
  id INT AUTO_INCREMENT PRIMARY KEY,
  quantity FLOAT NOT NULL,
  unitPrice FLOAT NOT NULL,
  tblImportReceipt2id INT NOT NULL,
  tblIngredient2id INT NOT NULL,
  FOREIGN KEY (tblImportReceipt2id) REFERENCES tblImportReceipt2(id),
  FOREIGN KEY (tblIngredient2id) REFERENCES tblIngredient2(id)
);
-- status: 'Còn món' | 'Tạm hết' | 'Ngừng kinh doanh' (chỉ NV quản lí cập nhật, qua chức năng Quản lí món ăn)
CREATE TABLE tblMenuItem2 (
  id INT AUTO_INCREMENT PRIMARY KEY,
  itemCode VARCHAR(20) NOT NULL UNIQUE,
  name VARCHAR(255) NOT NULL,
  category VARCHAR(50) NOT NULL,
  price FLOAT NOT NULL,
  unit VARCHAR(20) NOT NULL,
  `portion` VARCHAR(50) NULL,
  description VARCHAR(255) NULL,
  image VARCHAR(255) NULL,
  status VARCHAR(30) NOT NULL
);
CREATE TABLE tblCombo2 (
  id INT AUTO_INCREMENT PRIMARY KEY,
  name VARCHAR(255) NOT NULL,
  price FLOAT NOT NULL,
  description VARCHAR(255) NULL,
  status VARCHAR(30) NOT NULL
);
CREATE TABLE tblComboItem2 (
  id INT AUTO_INCREMENT PRIMARY KEY,
  quantity INT NOT NULL,
  tblCombo2id INT NOT NULL,
  tblMenuItem2id INT NOT NULL,
  FOREIGN KEY (tblCombo2id) REFERENCES tblCombo2(id),
  FOREIGN KEY (tblMenuItem2id) REFERENCES tblMenuItem2(id)
);
CREATE TABLE tblTable2 (
  id INT AUTO_INCREMENT PRIMARY KEY,
  name VARCHAR(20) NOT NULL,
  capacity INT NOT NULL
);
CREATE TABLE tblBooking2 (
  id INT AUTO_INCREMENT PRIMARY KEY,
  bookingTime DATETIME NOT NULL,
  arrivalTime DATETIME NOT NULL,
  checkInTime DATETIME NULL,
  numberOfGuests INT NOT NULL,
  note VARCHAR(255) NULL,
  tblCustomer2id INT NOT NULL,
  tblTable2id INT NOT NULL,
  tblEmployee2id INT NULL,
  FOREIGN KEY (tblCustomer2id) REFERENCES tblCustomer2(tblMember2id),
  FOREIGN KEY (tblTable2id) REFERENCES tblTable2(id),
  FOREIGN KEY (tblEmployee2id) REFERENCES tblEmployee2(tblMember2id)
);
CREATE TABLE tblOrder2 (
  id INT AUTO_INCREMENT PRIMARY KEY,
  orderTime DATETIME NOT NULL,
  orderType VARCHAR(20) NOT NULL,
  note VARCHAR(255) NULL,
  tblCustomer2id INT NULL,
  tblTable2id INT NULL,
  tblEmployee2id INT NOT NULL,
  tblBooking2id INT NULL UNIQUE,
  FOREIGN KEY (tblCustomer2id) REFERENCES tblCustomer2(tblMember2id),
  FOREIGN KEY (tblTable2id) REFERENCES tblTable2(id),
  FOREIGN KEY (tblEmployee2id) REFERENCES tblEmployee2(tblMember2id),
  FOREIGN KEY (tblBooking2id) REFERENCES tblBooking2(id)
);
CREATE TABLE tblOrderedMenuItem2 (
  id INT AUTO_INCREMENT PRIMARY KEY,
  quantity INT NOT NULL,
  price FLOAT NOT NULL,
  note VARCHAR(255) NULL,
  tblOrder2id INT NOT NULL,
  tblMenuItem2id INT NOT NULL,
  FOREIGN KEY (tblOrder2id) REFERENCES tblOrder2(id),
  FOREIGN KEY (tblMenuItem2id) REFERENCES tblMenuItem2(id)
);
CREATE TABLE tblOrderedCombo2 (
  id INT AUTO_INCREMENT PRIMARY KEY,
  quantity INT NOT NULL,
  price FLOAT NOT NULL,
  tblOrder2id INT NOT NULL,
  tblCombo2id INT NOT NULL,
  FOREIGN KEY (tblOrder2id) REFERENCES tblOrder2(id),
  FOREIGN KEY (tblCombo2id) REFERENCES tblCombo2(id)
);
CREATE TABLE tblInvoice2 (
  id INT AUTO_INCREMENT PRIMARY KEY,
  invoiceCode VARCHAR(20) NOT NULL UNIQUE,
  paymentTime DATETIME NOT NULL,
  discountAmount FLOAT NOT NULL,
  paymentMethod VARCHAR(50) NOT NULL,
  tblOrder2id INT NOT NULL UNIQUE,
  tblEmployee2id INT NOT NULL,
  tblMembershipCard2id INT NULL,
  FOREIGN KEY (tblOrder2id) REFERENCES tblOrder2(id),
  FOREIGN KEY (tblEmployee2id) REFERENCES tblEmployee2(tblMember2id),
  FOREIGN KEY (tblMembershipCard2id) REFERENCES tblMembershipCard2(id)
);














