-- ============================================================
-- SỬA HOÁ ĐƠN DÙNG THẺ TRƯỚC NGÀY CẤP THẺ: khách gọi món khi chưa đăng kí thẻ thì không có thẻ, không được giảm
-- ============================================================
UPDATE tblInvoice2 i JOIN tblMembershipCard2 k ON k.id = i.tblMembershipCard2id
SET i.tblMembershipCard2id = NULL, i.discountAmount = 0
WHERE DATE(i.paymentTime) < k.issueDate;

